# Import-Crews (Auswanderer, US-Soldaten, Japaner mit Liebe zu EU/US-Autos)
CREWS_C = [
dict(id='t_sleeper', name='Sleeper Agents', jp='スリーパー・エージェンツ', color='#90a4ae', tier=5, region='kagoshima',
 desc=('Amerikanische Familienlimousinen mit Frontantrieb und viel zu großen Motoren. Sehen aus wie Mietwagen am Flughafen, fahren wie Raketen.',
       'American family sedans with front-wheel drive and far too much engine. They look like airport rentals and drive like rockets.'),
 leader=('lansdale/38_tuner_late_M', 'Frank Whitaker', 'Der Agent', 'The Agent',
   'Kam als Austauschlehrer nach Kagoshima und blieb wegen der Vulkane. Behauptet, sein Lansdale sei ein Mietwagen, den er nie zurückgegeben hat.',
   'Came to Kagoshima as an exchange teacher and stayed for the volcanoes. Claims his Lansdale is a rental he never returned.', 'grey'),
 members=[
  ('lansdale/33_S_sport_A', 'Kenichi Ōshima', 'Mietwagen', 'Rental', 'Fährt, als gehöre das Auto nicht ihm. Es gehört ihm.', 'Drives like the car is not his. It is his.', 'silver'),
  ('lansdale/33_S_sport_late_A', 'Brenda Kowalski', 'Fußballmama', 'Soccer Mom', 'Zog mit ihrem Mann nach Japan und hat den Van gegen einen Lansdale getauscht. Der Mann war dagegen.', 'Moved to Japan with her husband and swapped the minivan for a Lansdale. Her husband objected.'),
  ('lansdale/38_SE_sport_AWD_A', 'Yasuo Tamura', 'Getarnt', 'Undercover', 'Hat einen Wackeldackel auf der Hutablage. Zur Tarnung.', 'Has a nodding dog on the parcel shelf. As camouflage.', 'beige'),
  ('lansdale/38_SE_sport_AWD_late_A', 'Dale Hutchins', 'Kreuzfahrer', 'Cruise Control', 'Fährt alles mit Tempomat. Auch die Kurven. Vor allem die Kurven.', 'Does everything on cruise control. Including the corners. Especially the corners.'),
  ('lansdale/38_race_late_M', 'Yoshiki Mae', 'Tourenwagen', 'Touring Car', 'Hat einen Lansdale zum Rennauto umgebaut. Seine Freunde haben gelacht, bis sie ihn von hinten sahen.', 'Turned a Lansdale into a race car. His friends laughed until they saw it from behind.'),
  ('wendover/se_v8_A', 'Harold Baines', 'Onkel Harold', 'Uncle Harold', 'Rentner aus Ohio, der in Japan seine Tochter besucht und nie wieder abgereist ist.', 'Retiree from Ohio who visited his daughter in Japan and never left.', 'burgundy'),
  ('wendover/se_v8_A_facelift', 'Mayumi Baines', 'Schwiegertochter', 'Daughter-in-Law', 'Harolds Schwiegertochter. Hat ihm den Wendover geklaut und fährt ihn besser.', 'Harold\'s daughter-in-law. Stole his Wendover and drives it better.'),
  ('wendover/sport_se_v6_A_facelift', 'Tomohiro Saeki', 'Polsterkönig', 'Upholstery King', 'Hat Samtsitze und eine Kühlbox zwischen den Sitzen. Für die Kühlbox fährt er vorsichtig.', 'Has velvet seats and a cooler between them. For the cooler he drives carefully.'),
  ('wendover/sport_se_v6_A', 'Gary Lindqvist', 'Schaumstoffwürfel', 'Fuzzy Dice', 'Hat Plüschwürfel am Spiegel, die bei jedem Bremsen eine Sechs würfeln.', 'Has fuzzy dice on his mirror that roll a six every time he brakes.'),
  ('legran/sport_se_v6_awd_facelift_A', 'Noriko Wells', 'Kombüse', 'Galley', 'Arbeitet als Köchin auf einem Frachter und fährt nur, wenn ihr Schiff im Hafen liegt.', 'Works as a cook on a freighter and only races when her ship is in port.'),
  ('legran/custom', 'Bob Ferraro', 'Bastler-Bob', 'Tinker Bob', 'Hat seinen Legran in der Garage eines Freundes umgebaut. Der Freund sucht die Garage noch.', 'Rebuilt his Legran in a friend\'s garage. The friend is still looking for the garage.'),
  ('legran/race', 'Shinya Legrand', 'Halbfranzose', 'Half French', 'Halb Japaner, halb Franzose, ganz Legran. Findet seinen Namen witzig. Als Einziger.', 'Half Japanese, half French, all Legran. Thinks his name is funny. The only one who does.'),
 ]),
dict(id='t_etkklassik', name='Bayern Kaze', jp='バイエルン風', color='#64b5f6', tier=6, region='shinagawa',
 desc=('Japaner mit einer Schwäche für deutsche Achtziger-Limousinen. Sie tragen Lederhandschuhe, sammeln Ersatzteile aus Stuttgart und reden über Lenkradpolster, als wäre es Philosophie.',
       'Japanese drivers with a soft spot for German eighties saloons. Leather gloves, spare parts from Stuttgart, and opinions on steering wheel padding that sound like philosophy.'),
 leader=('etki/cool', 'Wolfgang Takahashi', 'Der Knallharte', 'The Hard Case',
   'Halb Münchner, halb Osakaer, voll Knallhart. Bestellt im Izakaya immer Weißwurst und ist jedes Mal enttäuscht.',
   'Half Munich, half Osaka, all hard case. Orders white sausage at every izakaya and is always disappointed.'),
 members=[
  ('etki/3000i_M', 'Shigeru Bando', 'Autobahn-San', 'Autobahn-san', 'War einmal in Deutschland und fuhr dort 240. Erzählt es bei jeder Gelegenheit. Auch bei Beerdigungen.', 'Once drove 240 in Germany. Brings it up at every opportunity. Even at funerals.', 'silver'),
  ('etki/3000ix_M', 'Hanae Kröger', 'Allradtante', 'AWD Auntie', 'Hat einen deutschen Mann, einen deutschen Schäferhund und einen deutschen Allradler. In dieser Reihenfolge.', 'Has a German husband, a German shepherd and a German AWD. In that order.', 'forest'),
  ('etki/3000ix_A_alt', 'Takeshi Mertens', 'Kassenwart', 'Treasurer', 'Führt die Clubkasse und hat jede Schraube seit 1992 quittiert.', 'Keeps the club funds and has a receipt for every bolt since 1992.'),
  ('etki/3000ix_M_alt', 'Klaus Oyamada', 'Klaus-san', 'Klaus-san', 'Hat seinen Vornamen in Deutschland geändert und seinen Nachnamen in Japan behalten. Niemand versteht seine Visitenkarte.', 'Changed his first name in Germany and kept his surname in Japan. Nobody understands his business card.', 'navy'),
  ('etki/2400ti_sport_M', 'Rie Hoffmann', 'Bremsscheibe', 'Brake Disc', 'Wechselt ihre Bremsbeläge nach dem Mondkalender. Es funktioniert erstaunlich gut.', 'Changes her brake pads by the lunar calendar. It works surprisingly well.', 'white'),
  ('etki/2400ti_sport_M_alt', 'Jun Weber', 'Webers Junge', 'Weber\'s Boy', 'Hat den Wagen von seinem deutschen Großvater geerbt, inklusive Sitzbezug aus Schaffell.', 'Inherited the car from his German grandfather, including the sheepskin seat cover.'),
  ('etki/2400tix_sport_M', 'Ingrid Sato', 'Die Ingenieurin', 'The Engineer', 'Arbeitete bei ETK in Deutschland und kennt jeden Konstruktionsfehler. Hat die meisten selbst gemacht.', 'Worked at ETK in Germany and knows every design flaw. Made most of them herself.'),
  ('etki/2400tix_sport_M_alt', 'Masahiro Engel', 'Engelchen', 'Little Angel', 'Fährt engelsgleich und flucht dabei teuflisch. Auf Bayerisch.', 'Drives like an angel and swears like a devil. In Bavarian.', 'red'),
  ('etki/2400ti_sport_evo_M', 'Dieter Fukuda', 'Evolution', 'Evolution', 'Sagt, die Evo sei die einzige Version, die man ernst nehmen kann. Hat 14 Foren-Accounts, um das zu beweisen.', 'Says the Evo is the only version worth taking seriously. Runs 14 forum accounts to prove it.'),
  ('etki/2400tix_sport_evo_M', 'Midori Schulz', 'Grüner Pfeil', 'Green Arrow', 'Ihr Name bedeutet grün, ihr Auto ist grün, ihr Nachname ist deutsch. Sie fährt nur bei Grün. Meistens.', 'Her name means green, her car is green, her surname is German. She only goes on green. Mostly.', 'green'),
  ('etki/custom', 'Rainer Ishikawa', 'Ölwechsel', 'Oil Change', 'Hat in seiner Wohnung eine Hebebühne. Im Wohnzimmer.', 'Has a car lift in his flat. In the living room.'),
 ]),
dict(id='t_yokota', name='Night Patrol 16', jp='ナイトパトロール16', color='#7cb342', tier=7, region='okinawa_airforce',
 desc=('US-Soldaten von einem Stützpunkt im Westen Tokios, die nach Dienstschluss mit amerikanischen Pick-ups und V8 den Ring erobern. Laut, freundlich und immer mit Barbecue-Soße im Handschuhfach.',
       'US service members from a base west of Tokyo who take the loop after duty in American pickups and V8s. Loud, friendly, and always with barbecue sauce in the glovebox.'),
 leader=('roamer/street_tuned', 'Sgt. Marcus Delgado', 'Der Sergeant', 'The Sergeant',
   'Hat seinen Roamer in einem Frachtflugzeug mitgebracht. Offiziell als Ersatzteil. Brüllt Befehle durch das offene Fenster.',
   'Brought his Roamer over in a cargo plane. Officially listed as a spare part. Shouts orders through the open window.', 'olive'),
 members=[
  ('pickup/d15_ext_customclassic_M', 'Cpl. Jenny Morales', 'Lieferdienst', 'Supply Run', 'Fährt die Vorräte für die ganze Einheit. Wenn sie gewinnt, gibt es Pizza für alle.', 'Runs supplies for the whole unit. When she wins, everyone gets pizza.', 'sand'),
  ('pickup/d15_423sport_A', 'Pvt. Tyler Brooks', 'Frischling', 'Fresh Meat', 'Ist seit drei Wochen in Japan und hat schon zwei Strafzettel und einen Kendo-Lehrer.', 'Has been in Japan for three weeks and already has two parking tickets and a kendo teacher.'),
  ('pickup/d10_423sport_A', 'Sgt. Ray Washington', 'Charro', 'Charro', 'Trägt immer einen Cowboyhut. Auch im Auto. Er hat das Dach ausgebeult.', 'Always wears a cowboy hat. Even in the car. He dented the roof to make it fit.'),
  ('pickup/d15_track_awd_M', 'Lt. Amanda Price', 'Pistenflitzer', 'Runway Rocket', 'Ist Fluglotsin und fährt so, als hätte sie Startfreigabe. Hat sie aber nicht.', 'Is an air traffic controller and drives like she has take-off clearance. She does not.', 'olive'),
  ('pickup/d15_streettuned_M', 'Spc. Danny Okafor', 'Burnout', 'Burnout', 'Macht vor jedem Rennen einen Burnout. Der Stützpunkt hat ihm eigene Reifen-Rationen zugeteilt.', 'Does a burnout before every race. The base gave him his own tyre rations.'),
  ('fullsize/custom', 'MSgt. Earl Jennings', 'Großvater Earl', 'Grandpa Earl', 'Dient seit 26 Jahren, davon 20 in Japan. Spricht besser Japanisch als die meisten Japaner, aber nur Kansai-Dialekt.', 'Has served 26 years, 20 of them in Japan. Speaks better Japanese than most locals, but only Kansai dialect.', 'black'),
  ('fullsize/roadsport', 'Cpl. Kevin Nakamura-Reed', 'Halber Heimweg', 'Halfway Home', 'Japanische Mutter, amerikanischer Vater, und ein V8, der in beiden Ländern zu laut ist.', 'Japanese mother, American father, and a V8 too loud for either country.', 'navy'),
  ('roamer/sport', 'Sgt. Lisa Kim', 'Kartenleserin', 'Map Reader', 'Kann jede Karte lesen, außer die Speisekarte im Izakaya. Bestellt deshalb immer Nummer sieben.', 'Can read any map except the menu at the izakaya. So she always orders number seven.', 'sand'),
 ]),
dict(id='t_muscle73', name='Shōwa 48 Muscle', jp='昭和48マッスル', color='#ff7043', tier=8, region='toyota',
 desc=('Japaner, die mit amerikanischen Filmen aus den Siebzigern aufgewachsen sind und jetzt die Autos dazu fahren. Sie bremsen vor Kurven so früh, dass man sie für vorsichtig hält. Sind sie nicht.',
       'Japanese drivers who grew up on seventies American movies and now drive the cars from them. They brake so early for corners you think they are careful. They are not.'),
 leader=('barstow/custom', 'Kōtarō Nishikawa', 'Nachtschlange', 'Nightsnake',
   'Hat jeden amerikanischen Autofilm 40-mal gesehen und spricht nur in Zitaten. Sein Barstow riecht nach Benzin und Popcorn.',
   'Has seen every American car movie 40 times and speaks only in quotes. His Barstow smells of petrol and popcorn.'),
 members=[
  ('moonhawk/v8m_sport', 'Hiroyuki Gondō', 'Koteletten', 'Sideburns', 'Hat Koteletten bis zum Kinn und Schlaghosen im Kofferraum. Zum Wechseln.', 'Has sideburns down to his chin and flared trousers in the boot. For a change.', 'orange'),
  ('moonhawk/v8a_sport', 'Mamiko Takei', 'Discokugel', 'Disco Ball', 'Hat eine Discokugel im Innenraum und fährt nur zu Funk.', 'Has a disco ball inside and only drives to funk.', 'gold'),
  ('moonhawk/v8m_sport_alt', 'Jōji Fukui', 'Cowboy-Jōji', 'Cowboy George', 'Hat einen Sattel als Beifahrersitz. Niemand weiß, ob das legal ist.', 'Has a saddle for a passenger seat. Nobody knows if that is legal.', 'brown'),
  ('moonhawk/v8a_sport_alt', 'Rumi Kawabe', 'Autokino', 'Drive-In', 'Betreibt das letzte Autokino der Präfektur und fährt nach der Spätvorstellung Rennen.', 'Runs the last drive-in cinema in the prefecture and races after the late show.', 'teal'),
  ('moonhawk/v8special', 'Tsuyoshi Doi', 'V8-Spezial', 'V8 Special', 'Hat sein Auto 1998 gekauft und seitdem keinen Tag nüchtern über Hubraum geredet.', 'Bought his car in 1998 and has not spoken soberly about displacement since.'),
  ('moonhawk/drive', 'Yoshie Kobayakawa', 'Elite', 'Elite', 'Sagt, ihr Auto sei eine Elite-Custom. Ihr Mechaniker sagt, es sei ein Wunder.', 'Says her car is an Elite Custom. Her mechanic says it is a miracle.'),
  ('moonhawk/race', 'Ken Hollister', 'Oval-Ken', 'Oval Ken', 'Ex-Stockcar-Fahrer aus North Carolina. Findet es verwirrend, dass der Ring auch nach rechts abbiegt.', 'Ex stock car driver from North Carolina. Finds it confusing that the loop also turns right.'),
  ('barstow/tracksport', 'Daijirō Sano', 'Kreuzbandriss', 'Torn Ligament', 'Hat sich beim Einsteigen in seinen Barstow das Knie verdreht und fährt trotzdem jede Nacht.', 'Twisted his knee getting into his Barstow and still races every night.', 'red'),
  ('barstow/kingsnake', 'Asami Kurokawa', 'Königskobra', 'King Cobra', 'Hat eine echte Schlange zu Hause. Die Schlange heißt wie das Auto, das Auto heißt wie die Schlange.', 'Keeps a real snake at home. The snake is named after the car, the car after the snake.', 'green'),
 ]),
dict(id='t_hotrod', name='Kōenji Greasers', jp='高円寺グリーサーズ', color='#bcaaa4', tier=9, region='shinagawa',
 desc=('Rockabilly-Tolle, Lederjacke, Hot Rod. Die Greasers aus Kōenji fahren Autos, die älter sind als ihre Großeltern, mit Motoren, die jünger und viel zu stark sind.',
       'Rockabilly quiffs, leather jackets, hot rods. The Greasers from Kōenji drive cars older than their grandparents with engines that are younger and far too strong.'),
 leader=('burnside/gasser_late', 'Elvis Yamamoto', 'Der King', 'The King',
   'Heißt wirklich Elvis, seine Mutter war Fan. Kämmt sich vor jedem Rennen die Tolle und hat Pomade für drei Leben im Handschuhfach.',
   'Really is called Elvis, his mum was a fan. Combs his quiff before every race and has enough pomade for three lifetimes.'),
 members=[
  ('nine/nine_pickup_hotrod', 'Tommy Kagawa', 'Kugelfest', 'Bulletproof', 'Sagt, sein Pick-up sei kugelsicher. Hat es zum Glück nie ausprobiert.', 'Says his pickup is bulletproof. Luckily never tested it.'),
  ('nine/nine_drift', 'Sid Watanuki', 'Rinnsteinritter', 'Gutter Knight', 'Driftet einen Wagen von 1933. Das Auto hat schon zwei Weltkriege überlebt, aber Sid ist eine neue Gefahr.', 'Drifts a car from 1933. It survived the thirties and forties, but Sid is a new kind of danger.'),
  ('nine/nine_restomod', 'Peggy Sue Nakano', 'Phantom', 'Phantom', 'Fährt eine restaurierte Limousine mit modernem Motor und Petticoat. Den Petticoat trägt sie, nicht das Auto.', 'Drives a restored sedan with a modern engine and a petticoat. She wears the petticoat, not the car.', 'mint'),
  ('nine/nine_restomod_coupe', 'Johnny Ōsugi', 'Scharfer Anzug', 'Sharp Dressed', 'Trägt nur Anzüge, die zum Auto passen. Hat inzwischen vier Speedster-Anzüge.', 'Only wears suits that match his car. Now owns four speedster suits.', 'wine'),
  ('nine/nine_hotrod_60s', 'Buddy Hamano', 'Sonnenuntergang', 'Sundown', 'Fährt nur bei Sonnenuntergang los und kommt erst zum Sonnenaufgang zurück.', 'Only sets off at sundown and only comes back at sunrise.', 'orange'),
  ('nine/nine_hotbeams', 'Ricky Takamine', 'Scheinwerfer', 'Hot Beams', 'Hat so viele Scheinwerfer, dass er nachts einen Sonnenbrand bekommt.', 'Has so many headlights he gets a sunburn at night.'),
  ('burnside/leadsled', 'Lola Ishizuka', 'Bleischlitten', 'Lead Sled', 'Ihr Auto liegt so tief, dass sie beim Aussteigen auf dem Boden sitzt.', 'Her car is so low she is sitting on the ground when she gets out.', 'lilac'),
  ('burnside/custom', 'Rocky Ueda', 'Felsen', 'The Rock', 'Hat seinen Burnside selbst lackiert, mit Flammen. Die Flammen sind ungleichmäßig, er sagt, das sei Absicht.', 'Painted his Burnside himself, with flames. They are uneven and he says that was the plan.'),
  ('burnside/ratrod', 'Vinnie Kōno', 'Rostlaube', 'Rust Bucket', 'Sein Auto besteht zu 40 Prozent aus Rost und zu 60 Prozent aus Selbstvertrauen.', 'His car is 40 percent rust and 60 percent confidence.'),
 ]),
dict(id='t_bolide', name='Rosso Ottantuno', jp='ロッソ・オッタントゥーノ', color='#e53935', tier=10, region='shinagawa',
 desc=('Japanische Sammler italienischer Achtziger-Exoten. Sie fahren mit Fahrerhandschuhen, haben Ersatzteile in Mailand bestellt und warten seit 1997 darauf.',
       'Japanese collectors of eighties Italian exotics. Driving gloves on, spare parts ordered from Milan, still waiting since 1997.'),
 leader=('bolide/topspeed', 'Marco Kuroiwa', 'Vollgas-Marco', 'Flat-Out Marco',
   'Halb Italiener, halb Ehrgeiz. Hat seinen Bolide auf Höchstgeschwindigkeit getrimmt und den Rückspiegel abgebaut, weil er ihn nie braucht.',
   'Half Italian, half ambition. Set his Bolide up for top speed and removed the mirror, because he never needs it.', 'italred'),
 members=[
  ('bolide/350', 'Kazunari Ōmi', 'Poster an der Wand', 'Bedroom Poster', 'Hatte den Bolide als Kind als Poster an der Wand. Jetzt hat er das Auto und kein Geld mehr für Wände.', 'Had the Bolide as a poster on his wall as a kid. Now he has the car and no money left for walls.', 'italred'),
  ('bolide/350_targa', 'Silvia Okazaki', 'Haarspray', 'Hairspray', 'Fährt offen und braucht eine Dose Haarspray pro Rennen.', 'Drives with the top off and needs one can of hairspray per race.', 'white'),
  ('bolide/clubracer', 'Enzo Takasugi', 'Clubmeister', 'Club Champion', 'War dreimal Clubmeister in einem Club mit drei Mitgliedern.', 'Was club champion three times in a club with three members.'),
  ('bolide/rally_asphalt', 'Luigi Hamasaki', 'Gruppe 4', 'Group 4', 'Hat einen Rallye-Bolide und sucht seit Jahren eine Rallye, die er sich leisten kann.', 'Owns a rally Bolide and has spent years looking for a rally he can afford.'),
  ('bolide/390gt', 'Chiaki Morandi', 'Gelbe Gefahr', 'Yellow Peril', 'Hat einen italienischen Mann geheiratet, weil er einen gelben 390 GT hatte. Der Mann ist weg, das Auto ist geblieben.', 'Married an Italian because he owned a yellow 390 GT. The husband left, the car stayed.', 'italyellow'),
  ('bolide/390gt_targa', 'Paolo Shiraishi', 'Espresso', 'Espresso', 'Trinkt vor jedem Rennen drei Espressi und fährt dann genauso.', 'Drinks three espressos before every race and drives exactly like that.'),
  ('bolide/390gt_strada', 'Mayu Lombardi', 'Strada', 'Strada', 'Sagt, sie fahre nur auf der Straße, nie auf der Strecke. Ihr Strafregister sagt etwas anderes.', 'Says she only drives on the street, never the track. Her record says otherwise.', 'black'),
  ('bolide/320gtt', 'Gino Fujikawa', 'Corse', 'Corse', 'Hat nie ein echtes Rennen gefahren, trägt aber immer einen feuerfesten Overall. Auch beim Einkaufen.', 'Never raced for real but always wears a fireproof suit. Even to the shops.'),
  ('bolide/320gtt_targa', 'Bianca Haneda', 'Weiße Witwe', 'White Widow', 'Drei Ehemänner, drei Bolide. Die Autos hat sie behalten.', 'Three husbands, three Bolides. She kept the cars.', 'white'),
 ]),
dict(id='t_vivace', name='Périph Tokyo', jp='ペリフ東京', color='#5c6bc0', tier=10, region='shinagawa',
 desc=('Französische Auswanderer und ihre japanischen Freunde. Sie fahren Kompaktsportler, als wäre der Ring der Pariser Boulevard Périphérique, und hupen genauso viel.',
       'French expats and their Japanese friends. They drive hot hatches like the loop was the Paris Boulevard Périphérique, and honk just as much.'),
 leader=('vivace/ardente_tuned', 'Antoine Moreau', 'Le Patron', 'Le Patron',
   'Eröffnete eine Bäckerei in Ebisu und fährt nachts seine Croissants persönlich aus. Mit 500 PS, damit sie warm bleiben.',
   'Opened a bakery in Ebisu and delivers his croissants himself at night. With 500 hp, so they stay warm.', 'frenchblue'),
 members=[
  ('vivace/ardente_carminsport', 'Camille Fujiwara', 'Carmin', 'Carmin', 'Ihr Lippenstift hat dieselbe Farbe wie ihr Auto. Sie hat es extra mischen lassen.', 'Her lipstick is the exact colour of her car. She had it mixed specially.'),
  ('vivace/trackday_M', 'Julien Ōtani', 'Baguette', 'Baguette', 'Hat ein Baguette als Schaltknauf. Ein echtes. Er wechselt es jeden Morgen.', 'Uses a baguette as a gear knob. A real one. He replaces it every morning.'),
  ('vivace/ardente_track', 'Élodie Sakai', 'Mistral', 'Mistral', 'Kam aus Marseille und bringt den Wind mit. Hinter ihr flattern die Absperrbänder.', 'Came from Marseille and brings the wind with her. The barrier tape flaps behind her.'),
  ('vivace/vivace_S_350q_DCT', 'Hugo Tsuruta', 'Gourmet', 'Gourmet', 'Bewertet jede Raststätte mit Sternen. Bisher hat keine einen bekommen.', 'Rates every service area with stars. None has earned one yet.', 'frenchblue'),
  ('vivace/ardente_S_410Q_DCT', 'Sophie Kanemoto', 'Frisson', 'Frisson', 'Sagt, sie fahre nur für den Frisson, den Schauer. Den bekommst du, wenn sie im Rückspiegel auftaucht.', 'Says she only drives for the frisson, the shiver. You get it when she shows up in your mirror.', 'white'),
  ('vivace/vivace_S_410q_DCT', 'Pierre-Yves Abe', 'Arsen', 'Arsenic', 'Sein Auto heißt Arsenic, und so fühlt sich ein Rennen gegen ihn auch an. Langsam, dann plötzlich.', 'His car is called Arsenic and that is how racing him feels. Slowly, then all at once.'),
 ]),
dict(id='t_etkmodern', name='Rennspecht Kai', jp='レンシュペヒト会', color='#42a5f5', tier=11, region='shinagawa',
 desc=('Unternehmer aus Roppongi mit moderner deutscher Ingenieurskunst. Sie reden über Allradsysteme wie andere über Aktien und schlagen dich, bevor ihr Kaffee kalt ist.',
       'Entrepreneurs from Roppongi with modern German engineering. They talk about AWD systems like others talk about stocks, and beat you before their coffee gets cold.'),
 leader=('etk800/846_ttSport_custom_DCT', 'Heinrich Kurosaki', 'Der Vorstand', 'The Chairman',
   'Leitet ein Start-up, dessen Zweck niemand kennt. Sein ETK hat mehr Leistung als die Firma Umsatz.',
   'Runs a start-up nobody understands. His ETK makes more power than his company makes revenue.', 'gunmetal'),
 members=[
  ('etk800/844_track_M', 'Ren Lindemann', 'Rundenzeit', 'Lap Time', 'Zeigt dir seine Rundenzeiten auf der Smartwatch. Ungefragt. Mehrmals.', 'Shows you his lap times on his smartwatch. Unprompted. Repeatedly.'),
  ('etk800/846_340_M', 'Saya Brandt', 'Vorstandsassistentin', 'Executive Assistant', 'Organisiert Heinrichs Leben und fährt nachts schneller als er. Er weiß es nicht.', 'Organises Heinrich\'s life and drives faster than him at night. He does not know.', 'white'),
  ('etk800/856x_340_A', 'Tobias Ishiguro', 'Leasingrate', 'Lease Payment', 'Fährt einen Leasingwagen und fährt ihn, als würde er ihm gehören. Die Bank sieht das anders.', 'Drives a leased car like he owns it. The bank sees it differently.', 'silver'),
  ('etk800/856_ttsport_DCT', 'Yuri Fischer', 'Start-up', 'Start-up', 'Hat drei Firmen gegründet und alle wieder verkauft. Das Auto behält sie.', 'Founded three companies and sold them all. The car she is keeping.', 'black'),
  ('etk800/846_ttsport_heritage_M', 'Gunther Mori', 'Heritage', 'Heritage', 'Sammelt ausschließlich Sondermodelle. Sagt Heritage so oft, dass es keine Bedeutung mehr hat.', 'Only collects special editions. Says heritage so often it has lost all meaning.'),
  ('etk800/rennspecht_8r_A', 'Nora Kōzuki', 'Specht', 'Woodpecker', 'Hämmert so lange auf deine Stoßstange ein, bis du nachgibst. Wie ein Specht.', 'Keeps hammering at your bumper until you give in. Like a woodpecker.'),
  ('etk800/846x_ttsport_plus_DCT', 'Felix Hanamura', 'Plus', 'Plus', 'Kauft immer die Plus-Version. Von allem. Auch vom Kaffee.', 'Always buys the plus version. Of everything. Even coffee.', 'gunmetal'),
  ('etkc/kc8_ttsport_DCT', 'Marlene Ōta', 'Coupé-Queen', 'Coupé Queen', 'Fährt nur Coupés, weil vier Türen ihrer Meinung nach drei zu viel sind.', 'Only drives coupés, because in her opinion four doors are three too many.', 'pearl'),
  ('etkc/kc8x_ttsport_plus_DCT', 'Sven Akiyama', 'Allwetter', 'All Weather', 'Fährt bei jedem Wetter, auch bei Taifun. Besonders bei Taifun.', 'Races in any weather, even typhoons. Especially typhoons.'),
  ('etkc/rennspecht_kr_A', 'Annika Tōdō', 'Rennspecht', 'Rennspecht', 'Hat den Rennspecht KR direkt ab Werk bestellt und ist zur Abholung nach Deutschland geflogen. Zurück ist sie gefahren. Fast.', 'Ordered the Rennspecht KR straight from the factory and flew to Germany to collect it. She drove back. Almost.'),
 ]),
dict(id='t_bastion', name='Bastion Brotherhood', jp='バスティオン兄弟団', color='#ffb300', tier=12, region='okinawa_airforce',
 desc=('Moderne amerikanische Muscle Cars mit Kompressor, gefahren von Veteranen und Japanern, die Hubraum für eine Lebenseinstellung halten. Auf der Geraden sind sie Götter.',
       'Modern supercharged American muscle, driven by veterans and Japanese fans who think displacement is a way of life. On the straights they are gods.'),
 leader=('bastion/redtail_A', 'Col. Jack "Redtail" Harmon', 'Redtail', 'Redtail',
   'Pensionierter Kampfpilot, der nach seinem letzten Flug einfach in Japan geblieben ist. Fährt, als hätte er noch Nachbrenner.',
   'Retired fighter pilot who simply stayed in Japan after his last flight. Drives like he still has afterburners.'),
 members=[
  ('bastion/sport_A', 'Mike Tanaka-Brown', 'Burger', 'Burger', 'Betreibt einen Burgerladen in Fussa. Jeder Sieg gegen ihn ist ein Gratis-Burger, er hat noch keinen verloren.', 'Runs a burger joint in Fussa. Every win against him earns a free burger. He has not lost one yet.', 'red'),
  ('bastion/sport_M', 'Shōji Yamaguchi', 'Handschalter', 'Stick Shift', 'Sagt, echte Muscle Cars brauchen drei Pedale. Hat das auf T-Shirts drucken lassen.', 'Says real muscle cars need three pedals. Had it printed on T-shirts.', 'black'),
  ('bastion/sport_gt_A', 'Linda Carver', 'Highway Star', 'Highway Star', 'Singt beim Fahren Rocksongs aus den Siebzigern. Alle, in voller Länge.', 'Sings seventies rock songs while driving. All of them, full length.', 'white'),
  ('bastion/sport_gt_M', 'Ryōsuke Ōhara', 'Hubraum', 'Displacement', 'Antwortet auf jede Frage mit 6,5 Liter. Wie spät ist es? 6,5 Liter.', 'Answers every question with 6.5 litres. What time is it? 6.5 litres.', 'blue'),
  ('bastion/hotlap', 'Darnell Hayes', 'Hotlap', 'Hotlap', 'War Instruktor auf einer Rennstrecke in Texas. Gibt dir während des Rennens Tipps über Funk, den du nicht hast.', 'Was a track instructor in Texas. Gives you tips over a radio you do not have during the race.'),
  ('bastion/street_tuned', 'Kumiko Steele', 'Stahlfrau', 'Steel Lady', 'Ihr Mann ist bei der Navy, sie ist bei der Bastion. Sie sieht ihn seltener als ihren Kompressor.', 'Her husband is in the Navy, she is in the Bastion. She sees him less than her supercharger.'),
  ('bastion/battlehawk_A', 'Maj. Tony Russo', 'Battlehawk', 'Battlehawk', 'Hat seinen Battlehawk nach seiner alten Staffel benannt und fährt nur in Formation. Allein.', 'Named his Battlehawk after his old squadron and only drives in formation. Alone.', 'gunmetal'),
 ]),
dict(id='t_scintilla', name='Scintilla Salon', jp='シンティラ・サロン', color='#ce93d8', tier=12, region='shinagawa',
 desc=('Die reichsten Fahrer der Stadt, mit italienischen Supersportwagen, die mehr kosten als ein Haus in Setagaya. Sie fahren nicht für das Geld, sie fahren gegen dich, weil ihnen langweilig ist.',
       'The richest drivers in the city, in Italian supercars that cost more than a house in Setagaya. They do not race for money, they race you because they are bored.'),
 leader=('scintilla/custom', 'Valentina Saionji', 'Die Gräfin', 'The Countess',
   'Halb italienischer Adel, halb japanischer Konzern. Hat den Salon gegründet, weil ihr der Golfclub zu laut war.',
   'Half Italian nobility, half Japanese conglomerate. Founded the salon because the golf club was too loud.'),
 members=[
  ('scintilla/gt', 'Kenzaburō Ōtori', 'Der Erbe', 'The Heir', 'Hat das Auto zum 18. Geburtstag bekommen. Zum 19. ein zweites, weil das erste die falsche Farbe hatte.', 'Got the car for his 18th birthday. Got a second for his 19th because the first was the wrong colour.', 'italyellow'),
  ('scintilla/gt_spider', 'Isabella Nakatomi', 'Sonnenbrille', 'Sunglasses', 'Trägt nachts Sonnenbrille. Fährt trotzdem perfekt. Vermutlich Geld.', 'Wears sunglasses at night. Still drives perfectly. Probably money.', 'white'),
  ('scintilla/gts', 'Tadamasa Kujō', 'Kunstsammler', 'Art Collector', 'Hält sein Auto für ein Kunstwerk und stellt es im Museum aus, wenn er nicht fährt.', 'Considers his car a work of art and displays it in a museum when he is not driving.', 'pearl'),
  ('scintilla/gts_spider', 'Chiara Matsukata', 'Champagner', 'Champagne', 'Fährt mit einem Glas Champagner im Getränkehalter. Hat noch nie einen Tropfen verschüttet.', 'Drives with a glass of champagne in the cup holder. Has never spilt a drop.', 'champagne'),
  ('scintilla/gtx', 'Hideaki Sumitomo', 'Allrad-Aristokrat', 'AWD Aristocrat', 'Hat Allrad gewählt, weil ihm Hinterradantrieb zu gewöhnlich war.', 'Chose all-wheel drive because rear-wheel drive felt too common.', 'black'),
  ('scintilla/gtx_spider', 'Lucia Asakura', 'Yachtclub', 'Yacht Club', 'Kommt direkt vom Hafen, wo ihre Yacht liegt. Die Yacht ist langsamer.', 'Comes straight from the harbour where her yacht is moored. The yacht is slower.', 'skyblue'),
  ('scintilla/gts_corse', 'Riccardo Hōjō', 'Corse', 'Corse', 'Ist der einzige im Salon, der wirklich Rennen gefahren ist. Die anderen finden das etwas vulgär.', 'The only one in the salon who actually raced. The others find that slightly vulgar.', 'italred'),
  ('scintilla/gts_corse_spider', 'Aurora Daimon', 'Morgenröte', 'Aurora', 'Fährt nur bis Sonnenaufgang und frühstückt dann in einem Hotel, das ihr gehört.', 'Drives only until sunrise, then has breakfast at a hotel she owns.', 'orange'),
  ('scintilla/gts_topspeed', 'Massimo Ōkura', 'Velocità', 'Velocità', 'Will einmal 400 auf dem Ring fahren. Die Stadt hat ihn gebeten, es nicht zu tun.', 'Wants to do 400 on the loop once. The city has politely asked him not to.'),
 ]),
]
